('b1rel-words','b1-relationships','words','Jacy jesteśmy?','Характер и отношения','8 карточек · B1','Опиши характер и важные качества близких',9,'🤝',128,true,'','[]','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}'),
('b1rel-grammar','b1-relationships','grammar','Podobni czy różni?','Местоимения и сравнение','6 заданий · B1','Сравнивай людей и связывай описание местоимениями',12,'✏️',129,true,'Относительные местоимения и сравнение','[["Сравнение","Wyższy od brata и bardziej cierpliwa niż koleżanka показывают различие; tak samo… jak — равенство."],["Кто и который","Форма który меняется по роду, числу и роли: osoba, która pomaga; kolega, któremu ufam."],["Управление","Устойчивое выражение liczyć na требует винительного: przyjaciel, na którego liczę."]]','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}'),
('b1rel-review','b1-relationships','review','Jak znaleźć kompromis?','Конфликт и компромисс','7 карточек · B1','Обсуди разногласие и предложи решение',8,'🔄',130,true,'','[]','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}'),
('b1rel-quiz','b1-relationships','quiz','Quiz: relacje','Проверка темы','10 вопросов · B1','Проверь лексику, сравнение и местоимения',9,'🎯',131,true,'','[]','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}'),
('b1rel-reading-check','b1-relationships','quiz','Czy rozumiesz Olę i Michała?','Понимание текста','6 вопросов · B1','Найди причину конфликта и итоговый компромисс',7,'📖',132,true,'','[]','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}') on conflict(id) do update set topic_id=excluded.topic_id,kind=excluded.kind,title=excluded.title,plan_title=excluded.plan_title,subtitle=excluded.subtitle,description=excluded.description,minutes=excluded.minutes,emoji=excluded.emoji,position=excluded.position,is_active=excluded.is_active,theory_title=excluded.theory_title,theory_sections=excluded.theory_sections,source_metadata=excluded.source_metadata;
