insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values
('b1rel-grammar','Ania jest spokojniejsza ___ swojej siostry.','["od","niż od","z"]',0,'После сравнительной степени прилагательного естественна конструкция od + родительный падеж.',0),
('b1rel-grammar','To osoba, ___ mogę zaufać.','["której","którą","którego"]',0,'Глагол zaufać требует дательного падежа; форма женского относительного местоимения — której.',1),
('b1rel-grammar','Marek jest tak samo cierpliwy ___ Paweł.','["jak","niż","od"]',0,'Равная степень сравнения выражается конструкцией tak samo… jak.',2),
('b1rel-grammar','Nie lubię ludzi, ___ nie szanują cudzych granic.','["którzy","których","którym"]',0,'Местоимение является подлежащим во множественном числе, поэтому нужны którzy.',3),
('b1rel-grammar','Составьте: Моя сестра спокойнее меня, но мы хорошо понимаем друг друга.','["Moja siostra jest spokojniejsza ode mnie, ale dobrze się rozumiemy.","Moja siostra jest spokojna niż ja, ale rozumiemy nas.","Siostra spokojniejsza od ja i dobrze rozumie."]',0,'Сравнение требует spokojniejsza ode mnie, а взаимное действие — się rozumiemy.',4),
('b1rel-grammar','Составьте: Это друг, на которого я всегда могу рассчитывать.','["To przyjaciel, na którego zawsze mogę liczyć.","To przyjaciel, którego zawsze liczę.","To jest przyjaciel, na który mogę liczyć go."]',0,'Устойчивое выражение liczyć na kogoś требует na + винительный; для лица мужского рода — na którego.',5),
('b1rel-quiz','Что означает pójść na kompromis?','["пойти на взаимные уступки","прекратить общение","доказать свою правоту"]',0,'Pójść na kompromis — найти решение через взаимные уступки.',0),
('b1rel-quiz','Zawsze mogę ___ moją przyjaciółkę.','["liczyć na","różnić się","ustąpić do"]',0,'Liczyć na kogoś означает рассчитывать на человека.',1),
('b1rel-quiz','Osoba, która mówi prawdę, jest ___.','["szczera","uparta","obojętna"]',0,'Szczery описывает человека, который говорит открыто и правдиво.',2),
('b1rel-quiz','Piotr jest bardziej otwarty ___ brata.','["od","jak","z"]',0,'Сравнительная степень с od требует родительного падежа.',3),
('b1rel-quiz','To koleżanka, ___ opowiedziałem o problemie.','["której","która","którą"]',0,'Opowiedzieć komuś требует дательного падежа: której.',4),
('b1rel-quiz','Jesteśmy tak samo uparci ___ nasi rodzice.','["jak","od","niż od"]',0,'Равенство признака выражается tak samo… jak.',5),
('b1rel-quiz','Co najlepiej kończy nieporozumienie?','["spokojna, szczera rozmowa","unikanie każdej rozmowy","kolejna kłótnia"]',0,'Спокойный искренний разговор позволяет объяснить позиции.',6),
('b1rel-quiz','Выберите естественное сочетание.','["szanować czyjeś granice","robić charakter","liczyć kompromis"]',0,'Szanować czyjeś granice — устойчивое выражение об уважении личных границ.',7),
('b1rel-quiz','Nie zgadzaliśmy się, ale udało nam się ___.','["dogadać","kłócić do","różnić na"]',0,'Dogadać się означает прийти к взаимопониманию.',8),
('b1rel-quiz','Które zdanie opisuje dobrą relację?','["Potrafimy słuchać się nawzajem i czasem ustąpić.","Zawsze unikamy trudnych tematów.","Jedna osoba zawsze decyduje za obie."]',0,'Хорошие отношения предполагают взаимное слушание и готовность уступать.',9),
('b1rel-reading-check','Dlaczego Ola i Michał się pokłócili?','["Inaczej wyobrażali sobie wspólny wyjazd","Jedno z nich zgubiło telefon","Nie znali się wcześniej"]',0,'Конфликт начался из-за разных ожиданий от поездки.',0),
('b1rel-reading-check','Jak Ola zachowała się na początku?','["Przerywała Michałowi i broniła swojego planu","Od razu zgodziła się na wszystko","Wyszła bez słowa"]',0,'Сначала Оля перебивала и защищала только свой вариант.',1),
('b1rel-reading-check','Co zaproponował Michał?','["Żeby każde spokojnie powiedziało, czego potrzebuje","Żeby odwołać wyjazd","Żeby poprosić znajomych o decyzję"]',0,'Михал предложил по очереди объяснить потребности.',2),
('b1rel-reading-check','Czego potrzebowała Ola?','["Czasu na odpoczynek bez pośpiechu","Codziennych długich wędrówek","Samotnego wyjazdu"]',0,'Оле хотелось спокойного отдыха без спешки.',3),
('b1rel-reading-check','Na czym polegał kompromis?','["Połączyli spokojne poranki z aktywnymi popołudniami","Zrezygnowali z całego urlopu","Każde pojechało gdzie indziej"]',0,'Они объединили ожидания обоих в одном плане.',4),
('b1rel-reading-check','Czego nauczyła ich ta rozmowa?','["Różnica charakterów nie musi prowadzić do konfliktu","Najlepiej nigdy nie zmieniać zdania","Bliscy zawsze myślą tak samo"]',0,'Герои поняли, что различия можно обсуждать и согласовывать.',5);
insert into public.reading_texts(id,topic_id,title,description,level,minutes,emoji,paragraphs,glossary,source_metadata,position,is_active) values ('b1rel-weekend-na-dwa-sposoby','b1-relationships','Weekend na dwa sposoby','Как разговор о потребностях помогает найти компромисс','B1',8,'🤝','["Ola i Michał planowali pierwszy wspólny weekend w górach. Ola chciała odpocząć, długo spać i bez pośpiechu spacerować po miasteczku. Michał przygotował natomiast listę tras i uważał, że im ambitniejsza wycieczka, tym lepszy będzie wyjazd. Gdy pokazali sobie plany, szybko pojawiło się nieporozumienie.","Na początku Ola przerywała Michałowi i próbowała udowodnić, że jej pomysł jest rozsądniejszy. Michał, który zwykle jest bardziej cierpliwy od niej, również zaczął mówić podniesionym głosem. Oboje poczuli, że drugie nie szanuje jego potrzeb. Zamiast dalej się kłócić, zrobili krótką przerwę.","Po kilku minutach Michał zaproponował, żeby każde spokojnie powiedziało, na czym mu zależy. Ola wyjaśniła, że po trudnym tygodniu potrzebuje odpoczynku. Michał przyznał, że ruch pomaga mu odzyskać energię. Kiedy przestali się oceniać, łatwiej było im usłyszeć siebie nawzajem.","W końcu poszli na kompromis: poranki miały być spokojne, a po południu wybierali jedną krótszą trasę. Weekend okazał się udany. Ola i Michał zrozumieli, że różnią się charakterem, lecz mogą na siebie liczyć. Szczera rozmowa nie usuwa wszystkich różnic, ale pomaga szanować granice i budować zaufanie."]','{"wyobrażali":{"lemma":"wyobrażać sobie","translation":"представлять себе","part_of_speech":"глагол"},"wspólny":{"lemma":"wspólny","translation":"совместный","part_of_speech":"прилагательное"},"bez pośpiechu":{"lemma":"bez pośpiechu","translation":"не спеша","part_of_speech":"выражение"},"ambitniejsza":{"lemma":"ambitny","translation":"более сложный; амбициозный","part_of_speech":"прилагательное"},"nieporozumienie":{"lemma":"nieporozumienie","translation":"недопонимание","part_of_speech":"существительное"},"przerywała":{"lemma":"przerywać","translation":"перебивать","part_of_speech":"глагол"},"udowodnić":{"lemma":"udowodnić","translation":"доказать","part_of_speech":"глагол"},"rozsądniejszy":{"lemma":"rozsądny","translation":"более разумный","part_of_speech":"прилагательное"},"podniesionym głosem":{"lemma":"podniesionym głosem","translation":"повышенным голосом","part_of_speech":"выражение"},"zależy":{"lemma":"zależeć","translation":"быть важным","part_of_speech":"глагол"},"przyznał":{"lemma":"przyznać","translation":"признать","part_of_speech":"глагол"},"odzyskać":{"lemma":"odzyskać","translation":"восстановить","part_of_speech":"глагол"},"nawzajem":{"lemma":"nawzajem","translation":"друг друга; взаимно","part_of_speech":"наречие"},"kompromis":{"lemma":"kompromis","translation":"компромисс","part_of_speech":"существительное"},"różnią się":{"lemma":"różnić się","translation":"отличаться","part_of_speech":"глагол"},"zaufanie":{"lemma":"zaufanie","translation":"доверие","part_of_speech":"существительное"}}','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30","comprehension_lesson_id":"b1rel-reading-check"}',28,true) on conflict(id) do update set topic_id=excluded.topic_id,title=excluded.title,description=excluded.description,level=excluded.level,minutes=excluded.minutes,emoji=excluded.emoji,paragraphs=excluded.paragraphs,glossary=excluded.glossary,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
